import React, { createContext, useState, useContext, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from './AuthContext';

const CartContext = createContext();

export const useCart = () => useContext(CartContext);

export const CartProvider = ({ children }) => {
  const [cartItems, setCartItems] = useState([]);
  const { token } = useAuth();

  useEffect(() => {
    if (token) {
      getCart();
    }
  }, [token]);

  const getCart = async () => {
    try {
      const res = await axios.get('http://localhost:5000/api/users/cart');
      setCartItems(res.data);
    } catch (err) {
      console.error(err.response.data);
    }
  };

  const addItem = async (item) => {
    const config = {
      headers: {
        'Content-Type': 'application/json',
      },
    };

    const body = JSON.stringify({ itemId: item.id, quantity: 1 });

    try {
      const res = await axios.post('http://localhost:5000/api/users/cart', body, config);
      setCartItems(res.data);
    } catch (err) {
      console.error(err.response.data);
    }
  };

  const removeItem = async (itemId) => {
    try {
      const res = await axios.delete(`http://localhost:5000/api/users/cart/${itemId}`);
      setCartItems(res.data);
    } catch (err) {
      console.error(err.response.data);
    }
  };

  const updateQuantity = async (itemId, quantity) => {
    if (quantity <= 0) {
      return removeItem(itemId);
    }

    const config = {
      headers: {
        'Content-Type': 'application/json',
      },
    };

    const body = JSON.stringify({ quantity });

    try {
      const res = await axios.put(`http://localhost:5000/api/users/cart/${itemId}`, body, config);
      setCartItems(res.data);
    } catch (err) {
      console.error(err.response.data);
    }
  };

  const clearCart = () => {
    // This will be handled by the backend when an order is created
    setCartItems([]);
  };

  const value = {
    cartItems,
    addItem,
    removeItem,
    updateQuantity,
    clearCart,
  };

  return <CartContext.Provider value={value}>{children}</CartContext.Provider>;
};
